// Normaliza payload do Tally (webhook FORM_RESPONSE)
const body = $input.first().json.body ?? $input.first().json;
const data = body.data ?? body;
const fields = data.fields ?? [];

const JOBS = [
  'Full Stack Developer',
  'Data Analyst',
  'HR Assistant',
  'Product Designer',
];

function resolveOption(field, raw) {
  if (raw == null) return null;
  if (typeof raw === 'object') {
    return raw.text ?? raw.label ?? raw.name ?? raw.value ?? null;
  }
  const s = String(raw);
  const opts = field.options || field.fieldOptions || [];
  const hit = opts.find((o) => o.id === s || o.uuid === s || o.value === s || o.text === s);
  if (hit) return hit.text ?? hit.label ?? hit.name ?? hit.value ?? s;
  if (/^[0-9a-f-]{36}$/i.test(s)) return null;
  return s;
}

function fieldRaw(labelOrKey) {
  return fields.find(
    (x) =>
      (x.label && String(x.label).toLowerCase() === String(labelOrKey).toLowerCase()) ||
      x.key === labelOrKey ||
      (x.title && String(x.title).toLowerCase() === String(labelOrKey).toLowerCase())
  );
}

function fieldValue(labelOrKey) {
  const f = fieldRaw(labelOrKey);
  if (!f) return null;
  if (Array.isArray(f.value)) {
    if (f.value[0]?.url) return f.value;
    return f.value
      .map((v) => resolveOption(f, v))
      .filter((x) => x != null && x !== '')
      .join(', ');
  }
  return resolveOption(f, f.value);
}

function extractResume(files) {
  const out = [];
  const arr = Array.isArray(files) ? files : files ? [files] : [];
  for (const f of arr) {
    if (!f) continue;
    if (typeof f === 'string' && f.startsWith('http')) {
      out.push({ url: f, filename: 'curriculo.pdf' });
      continue;
    }
    const url = f.url || f.downloadUrl || f.href;
    if (!url) continue;
    const filename =
      f.name ||
      f.filename ||
      f.originalName ||
      String(url).split('?')[0].split('/').pop() ||
      'curriculo.pdf';
    out.push({ url, filename });
  }
  return out;
}

const nome = fieldValue('Nome completo') ?? fieldValue('Nome') ?? data.nome ?? 'Sem nome';
const email = fieldValue('E-mail') ?? fieldValue('Email') ?? data.email ?? '';
let vaga = fieldValue('Vaga de interesse') ?? fieldValue('Vaga') ?? data.vaga ?? '';
if (!vaga || /^[0-9a-f-]{36}$/i.test(String(vaga))) {
  vaga = JOBS.includes(String(vaga)) ? vaga : 'Full Stack Developer';
}
if (!JOBS.includes(vaga)) {
  const approx = JOBS.find((j) => String(vaga).toLowerCase().includes(j.toLowerCase().split(' ')[0]));
  vaga = approx || 'Full Stack Developer';
}
const linkedin = fieldValue('LinkedIn') ?? '';
const resumo = fieldValue('Conte um pouco da sua experiência') ?? fieldValue('Resumo') ?? '';
const curriculoRaw = fieldValue('Currículo (PDF)') ?? fieldValue('Currículo') ?? [];
const resume = extractResume(curriculoRaw);

const submissionId = data.responseId ?? data.submissionId ?? body.eventId ?? $execution.id;

return [{
  json: {
    nome,
    email,
    vaga,
    linkedin,
    resumo,
    curriculo: curriculoRaw,
    resume,
    resume_url: resume[0]?.url || '',
    resume_filename: resume[0]?.filename || 'curriculo.pdf',
    tally_submission_id: String(submissionId),
    status_inicial: 'Under_Review',
    recebido_em: new Date().toISOString()
  }
}];

const ctx = $('Contexto Candidato').item.json;
const raw = $input.first().json;

let score = null;
let classification = 'Medium';
let reason = '';
let skills = [];
let nextStep = 'Revisão manual';
let iaOk = true;
let erroDetalhe = '';

function looksLikeRateLimit(v) {
  const s = typeof v === 'string' ? v : JSON.stringify(v ?? '');
  return /\b429\b|RESOURCE_EXHAUSTED|rate.?limit|quota|Try spacing your requests/i.test(s);
}

function extractText(obj) {
  if (obj == null) return null;
  if (typeof obj === 'string') return obj;

  // Native Gemini message content wrapper: { content: { parts: [{ text }], role } }
  const partText =
    obj.content?.parts?.[0]?.text ??
    obj.candidates?.[0]?.content?.parts?.[0]?.text ??
    obj.parts?.[0]?.text;
  if (partText != null) return partText;

  // simplify/jsonOutput may return parsed object under content/text
  if (obj.content != null && typeof obj.content === 'object' && !Array.isArray(obj.content)) {
    if (obj.content.score != null || obj.content.classification != null) return obj.content;
  }
  if (typeof obj.content === 'string') return obj.content;
  if (obj.text != null) return obj.text;
  if (obj.output != null) return obj.output;
  if (typeof obj.message === 'string') return obj.message;
  if (obj.score != null || obj.classification != null || obj.reason != null) return obj;
  if (obj.data) return extractText(obj.data);
  if (obj.json) return extractText(obj.json);
  return null;
}

function parsePayload(textOrObj) {
  if (textOrObj && typeof textOrObj === 'object' && !Array.isArray(textOrObj)) {
    return textOrObj;
  }
  let cleaned = String(textOrObj ?? '')
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  if (cleaned && cleaned[0] !== '{') {
    const m = cleaned.match(/\{[\s\S]*\}/);
    if (m) cleaned = m[0];
  }
  return JSON.parse(cleaned);
}

try {
  if (raw.error || raw.name === 'NodeApiError' || raw.name === 'AxiosError' || looksLikeRateLimit(raw)) {
    throw new Error(
      JSON.stringify(raw.error || { message: raw.message, status: raw.status, name: raw.name }),
    );
  }
  if (
    typeof raw.message === 'string' &&
    /error|failed|429/i.test(raw.message) &&
    raw.score == null &&
    !raw.candidates &&
    !raw.content
  ) {
    throw new Error(raw.message);
  }

  const extracted = extractText(raw);
  if (extracted == null || extracted === '') throw new Error('Empty Gemini response');

  const parsed = parsePayload(extracted);
  score = Number(parsed.score);
  classification = parsed.classification || 'Medium';
  reason = parsed.reason || parsed.ai_reason || '';
  skills = parsed.skills || parsed.extracted_skills || [];
  nextStep = parsed.next_step || parsed.suggested_next_step || nextStep;
  if (Number.isNaN(score)) {
    throw new Error('Invalid score from: ' + JSON.stringify(parsed).slice(0, 200));
  }
  if (!['High', 'Medium', 'Low'].includes(classification)) {
    const c = String(classification).toLowerCase();
    if (c.includes('high') || c.includes('alta')) classification = 'High';
    else if (c.includes('low') || c.includes('baixa')) classification = 'Low';
    else classification = 'Medium';
  }
} catch (e) {
  iaOk = false;
  erroDetalhe = String(e.message || e).slice(0, 1500);
  score = null;
  classification = 'Medium';
  reason = 'Falha da IA - encaminhado para revisão humana';
  nextStep = 'Revisão manual HITL';
}

const scoreHitlMin = Number($env.SCORE_HITL_MINIMO || 50);
const precisaHitl = !iaOk || (score !== null && score >= scoreHitlMin);

const baseId = String($env.AIRTABLE_BASE_ID || 'app32RqD9lvG8Sb0J');
const tableId = String($env.AIRTABLE_TABLE_ID || 'tblbzeyF946ZBbVSJ');
const recordId = String(ctx.airtable_id || ctx.id || '');
const recordUrl = 'https://airtable.com/' + baseId + '/' + tableId + '/' + recordId;
const webhookBase = String($env.WEBHOOK_URL || 'http://localhost:5678/').replace(/\/$/, '');
const approveUrl =
  webhookBase + '/webhook/hitl-decisao?recordId=' + encodeURIComponent(recordId) + '&decision=approve';
const rejectUrl =
  webhookBase + '/webhook/hitl-decisao?recordId=' + encodeURIComponent(recordId) + '&decision=reject';

return [
  {
    json: {
      ...ctx,
      record_url: recordUrl,
      approve_url: approveUrl,
      reject_url: rejectUrl,
      score,
      classification,
      motivo_ia: reason,
      ai_reason: reason,
      skills_extraidas: Array.isArray(skills) ? skills.join(', ') : String(skills),
      extracted_skills: Array.isArray(skills) ? skills.join(', ') : String(skills),
      proximo_passo_sugerido: nextStep,
      suggested_next_step: nextStep,
      ia_ok: iaOk,
      erro_detalhe: erroDetalhe,
      precisa_hitl: precisaHitl,
      score_hitl_minimo: scoreHitlMin,
    },
  },
];

