const input = $input.first().json;
const q = input.query ?? {};
const body = input.body ?? {};
const headers = input.headers ?? {};
const ua = String(headers['user-agent'] || headers['User-Agent'] || '').toLowerCase();
const recordId = String(
  q.recordId || q.record_id || body.recordId || body.record_id || input.recordId || ''
).trim();
const decision = String(
  q.decision || body.decision || input.decision || ''
).toLowerCase().trim();
const confirm = String(q.confirm || body.confirm || '').toLowerCase().trim();
const confirmed = ['1', 'true', 'yes', 'sim'].includes(confirm);

const aprovado = ['approve', 'aprovado', 'approved'].includes(decision);
const reprovado = ['reject', 'reprovado', 'rejected'].includes(decision);

if (!recordId) {
  return [{ json: { ok: false, needs_confirm: false, error: 'recordId obrigatório', recordId: '', hitl_aprovado: false, decision: '' } }];
}
if (!aprovado && !reprovado) {
  return [{ json: { ok: false, needs_confirm: false, error: 'decision inválida (use approve|reject)', recordId, hitl_aprovado: false, decision } }];
}

const base = String($env.WEBHOOK_URL || 'http://localhost:5678/').replace(/\/$/, '');
const decisionNorm = aprovado ? 'approve' : 'reject';
const label = aprovado ? 'Aprovar' : 'Reprovar';
const confirmUrl = `${base}/webhook/hitl-decisao?recordId=${encodeURIComponent(recordId)}&decision=${decisionNorm}&confirm=1`;

// Slack link unfurl hits GET without confirm — show confirmation page instead of deciding.
const isSlackUnfurl = ua.includes('slackbot') || ua.includes('slack-imgproxy') || ua.includes('slack-linkexpanding');
if (!confirmed || isSlackUnfurl) {
  return [{
    json: {
      ok: false,
      needs_confirm: true,
      error: 'confirm_required',
      recordId,
      decision: decisionNorm,
      hitl_aprovado: aprovado,
      confirm_url: confirmUrl,
      label
    }
  }];
}

return [{
  json: {
    ok: true,
    needs_confirm: false,
    recordId,
    airtable_id: recordId,
    decision: decisionNorm,
    hitl_aprovado: aprovado,
    hitl_raw: decision
  }
}];

const prev = $('Parse Parametros HITL').item.json;
const raw = $input.first().json;
const f = raw.fields || raw;

const nome = f.Name || f.nome || '';
const email = f.Email || f.email || '';
const vaga = f.Job || f.vaga || '';

return [{
  json: {
    ...prev,
    airtable_id: raw.id || prev.recordId,
    nome,
    email,
    vaga,
    status_atual: f.Status || '',
    human_decision_atual: f.Human_Decision || ''
  }
}];
